
/*
 * DE10-Standard: HPS controls FPGA LEDs through Lightweight HPS-to-FPGA bridge.
 * Based on the HPS_FPGA_LED example and Lab 4 requirements.
 *
 * LEDR0: heartbeat generated by the unchanged FPGA top-level logic.
 * LEDR1..8: a dark LED moves from one end to the other and back, 60 cycles.
 * LEDR9: one ON/OFF pulse at the end of each full cycle.
 */

#include <stdio.h>
#include <stdint.h>                 /* [M1] uint32_t */
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include "hwlib.h"
#include "socal/socal.h"
#include "socal/hps.h"
#include "socal/alt_gpio.h"
#include "hps_0.h"

#define HW_REGS_BASE ( ALT_STM_OFST )
#define HW_REGS_SPAN ( 0x04000000 )
#define HW_REGS_MASK ( HW_REGS_SPAN - 1 )

/* [M2] 8 output bits of led_pio are wired to LEDR[8:1] in the lab top level. */
#define SHIFT_LED_MASK      ( 0xFFU )
#define SHIFT_LED_LAST_BIT  ( 0x80U )

int main(void)
{
    void *virtual_base;
    int fd;
    int loop_count = 0;
    int led_direction = 0; /* 0: toward LEDR8; 1: back toward LEDR1 */
    uint32_t led_mask = 0x01U;
    void *h2p_lw_led_addr;
    void *h2p_lw_led9_addr; /* [M3] Declare the missing PIO9 pointer. */

    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd == -1) {
        printf("ERROR: could not open \"/dev/mem\"...\n");
        return 1;
    }

    virtual_base = mmap(NULL, HW_REGS_SPAN,
                        PROT_READ | PROT_WRITE, MAP_SHARED, fd, HW_REGS_BASE);
    if (virtual_base == MAP_FAILED) {
        printf("ERROR: mmap() failed...\n");
        close(fd);
        return 1;
    }

    /* [M4] Compute both register addresses from the generated hps_0.h. */
    h2p_lw_led_addr = (char *)virtual_base +
        ((unsigned long)(ALT_LWFPGASLVS_OFST + LED_PIO_BASE) &
         (unsigned long)HW_REGS_MASK);
    h2p_lw_led9_addr = (char *)virtual_base +
        ((unsigned long)(ALT_LWFPGASLVS_OFST + LED_PIO9_BASE) &
         (unsigned long)HW_REGS_MASK);

    *(volatile uint32_t *)h2p_lw_led9_addr = 0U; /* Initially off. */

    while (loop_count < 60) {
        /* [M5] Preserve the original ~led_mask (one dark LED moves). */
        *(volatile uint32_t *)h2p_lw_led_addr =
            (~led_mask) & SHIFT_LED_MASK;
        usleep(100 * 1000);

        if (led_direction == 0) {
            if (led_mask == SHIFT_LED_LAST_BIT) {
                led_direction = 1;
                led_mask >>= 1;
            } else {
                led_mask <<= 1;
            }
        } else {
            if (led_mask == 0x01U) {
                /* [M6] LEDR1..8 have completed one full back-and-forth. */
                loop_count++;
                led_direction = 0;
                led_mask = 0x01U;

                /* [M7] Blink LEDR9 once per completed cycle. */
                *(volatile uint32_t *)h2p_lw_led9_addr = 0x1U;
                usleep(100 * 1000);
                *(volatile uint32_t *)h2p_lw_led9_addr = 0x0U;
            } else {
                led_mask >>= 1;
            }
        }
    }

    /* [M8] Leave controlled LEDs off when the program exits. */
    *(volatile uint32_t *)h2p_lw_led_addr = 0U;
    *(volatile uint32_t *)h2p_lw_led9_addr = 0U;

    if (munmap(virtual_base, HW_REGS_SPAN) != 0) {
        printf("ERROR: munmap() failed...\n");
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}
